public void tick() {
        super.tick();
        prevScreenShakeAmount = screenShakeAmount;
        this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, yBodyRot, getHeadRotSpeed());
        this.legSolver.update(this, this.yBodyRot, this.getScale());
        AnimationHandler.INSTANCE.updateAnimations(this);
        if (screenShakeAmount > 0) {
            screenShakeAmount = Math.max(0, screenShakeAmount - 0.34F);
        }
        if (this.onGround() && !this.isInFluidType() && this.walkAnimation.speed() > 0.1F && !this.isBaby()) {
            float f = (float) Math.cos(this.walkAnimation.position() * 0.8F - 1.5F);
            if (Math.abs(f) < 0.2) {
                if (screenShakeAmount <= 0.3) {
                    this.playSound(ACSoundRegistry.TREMORSAURUS_STOMP.get(), 2, 1.0F);
                    this.shakeWater();
                }
                screenShakeAmount = 1F;
            }
        }
        if (this.tickCount % 100 == 0 && this.getHealth() < this.getMaxHealth()) {
            this.heal(2);
        }
        if (isRunning() && !hasRunningAttributes) {
            hasRunningAttributes = true;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.35D);
        }
        if (!isRunning() && hasRunningAttributes) {
            hasRunningAttributes = false;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.2D);
        }
        if(this.getAnimation() == ANIMATION_ROAR && this.getAnimationTick() == 5){
            this.playRoarSound();
        }
        if (this.getAnimation() == ANIMATION_ROAR && this.getAnimationTick() >= 5 && this.getAnimationTick() <= 40 && !this.isBaby()) {
            screenShakeAmount = 1F;
            roarScatterTime = 30;
            if (this.getAnimationTick() % 5 == 0 && level().isClientSide) {
                this.shakeWater();
            }
        }
        if (roarScatterTime > 0) {
            roarScatterTime--;
            scareMobs();
        }
        if (this.getAnimation() == ANIMATION_SPEAK && this.getAnimationTick() == 5) {
            actuallyPlayAmbientSound();
        }
        if (!level().isClientSide) {
            if (this.getDeltaMovement().horizontalDistance() < 0.05 && this.getAnimation() == NO_ANIMATION && !this.isDancing() && !this.isInSittingPose()) {
                if (random.nextInt(180) == 0) {
                    this.setAnimation(ANIMATION_SNIFF);
                }
                if (random.nextInt(600) == 0 && !this.isVehicle()) {
                    this.tryRoar();
                }
            }
            boolean held = false;
            if (riderHitEntity != null && this.getAnimation() == ANIMATION_BITE && this.getAnimationTick() > 10 && this.getAnimationTick() <= 12) {
                if (this.hasLineOfSight(riderHitEntity) && this.distanceTo(riderHitEntity) < this.getBbWidth() + riderHitEntity.getBbWidth() + 2.0D) {
                    riderHitEntity.hurt(riderHitEntity.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
                    if (riderHitEntity instanceof LivingEntity living) {
                        living.knockback(0.5D, this.getX() - riderHitEntity.getX(), this.getZ() - riderHitEntity.getZ());
                    }
                    riderHitEntity = null;
                }
            }
            LivingEntity target = riderHitEntity instanceof LivingEntity ? (LivingEntity) riderHitEntity : this.getTarget();
            if (target != null && target.isAlive() && target.distanceTo(this) < (isVehicle() ? 10.0F : 5.5F)) {
                if (this.getAnimation() == ANIMATION_SHAKE_PREY && this.getAnimationTick() <= 35) {
                    held = true;
                    this.setHeldMobId(target.getId());
                }
            }
            if (!held && getHeldMobId() != -1) {
                this.setHeldMobId(-1);
                this.playSound(ACSoundRegistry.TREMORSAURUS_THROW.get());
                riderHitEntity = null;
            }
        } else {
            Player player = AlexsCaves.PROXY.getClientSidePlayer();
            if (player != null && player.isPassengerOfSameVehicle(this)) {
                if (AlexsCaves.PROXY.isKeyDown(2) && getMeterAmount() >= 1.0F) {
                    AlexsCaves.sendMSGToServer(new MountedEntityKeyMessage(this.getId(), player.getId(), 2));
                }
                if (AlexsCaves.PROXY.isKeyDown(3) && (this.getAnimation() == NO_ANIMATION || this.getAnimation() == null)) {
                    AlexsCaves.sendMSGToServer(new MountedEntityKeyMessage(this.getId(), player.getId(), 3));
                }
            }
        }
        if (this.isVehicle()) {
            if (this.getMeterAmount() < 1.0F) {
                this.setMeterAmount(Math.min(this.getMeterAmount() + 0.0035F, 1.0F));
            }
        } else {
            this.setMeterAmount(0.0F);
        }
        if(this.getAnimation() == ANIMATION_SHAKE_PREY && getHeldMobId() != -1){
            Entity entity = level().getEntity(getHeldMobId());
            if(entity != null){
                if (this.getAnimationTick() <= 35) {
                    Vec3 shakePreyPos = getShakePreyPos();
                    Vec3 minus = new Vec3(shakePreyPos.x - entity.getX(), shakePreyPos.y - entity.getY(), shakePreyPos.z - entity.getZ());
                    entity.setDeltaMovement(minus);
                    if (this.getAnimationTick() % 10 == 0) {
                        entity.hurt(damageSources().mobAttack(this), 5 + this.getRandom().nextInt(2));
                    }
                }else{
                    entity.setDeltaMovement(entity.getDeltaMovement().scale(0.6F));
                }
            }
        }
        if (roarCooldown > 0) {
            roarCooldown--;
        }
        lastStompX = this.getX();
        lastStompZ = this.getZ();
    }

@Override
    public void onKeyPacket(Entity keyPresser, int type) {
        if (keyPresser.isPassengerOfSameVehicle(this)) {
            if (type == 2) {
                if (this.getMeterAmount() >= 1.0F && (this.getAnimation() == NO_ANIMATION || this.getAnimation() == null)) {
                    this.yBodyRot = keyPresser.getYHeadRot();
                    this.setYRot(keyPresser.getYHeadRot());
                    this.setAnimation(ANIMATION_ROAR);
                    this.setMeterAmount(0.0F);
                }
            }
            if (type == 3) {
                if (this.getAnimation() == NO_ANIMATION || this.getAnimation() == null) {
                    HitResult hitresult = ProjectileUtil.getHitResultOnViewVector(keyPresser, entity -> !entity.is(this) && !this.isAlliedTo(entity), 10.0F);
                    this.setYHeadRot(keyPresser.getYHeadRot());
                    this.setXRot(keyPresser.getXRot());
                    boolean flag = false;
                    if (hitresult instanceof EntityHitResult entityHitResult) {
                        riderHitEntity = entityHitResult.getEntity();
                        if (this.getRandom().nextBoolean() && riderHitEntity.getBbWidth() < 2.0F || riderHitEntity instanceof FlyingAnimal) {
                            flag = true;
                        }
                    } else {
                        riderHitEntity = null;
                    }
                    this.setAnimation(flag ? ANIMATION_SHAKE_PREY : ANIMATION_BITE);
                }
            }
        }
    }

public static void handle(MountedEntityKeyMessage message, Supplier<NetworkEvent.Context> context) {
        context.get().enqueueWork(() -> {
            Player playerSided = context.get().getSender();
            if (context.get().getDirection().getReceptionSide() == LogicalSide.CLIENT) {
                playerSided = AlexsCaves.PROXY.getClientSidePlayer();
            }
            Entity parent = playerSided.level().getEntity(message.mountId);
            Entity keyPresser = playerSided.level().getEntity(message.playerId);
            if (keyPresser != null && parent instanceof KeybindUsingMount mount && keyPresser instanceof Player && keyPresser.isPassengerOfSameVehicle(parent)) {
                mount.onKeyPacket(keyPresser, message.type);
            }
        });
        context.get().setPacketHandled(true);
    }

public void tick() {
        super.tick();
        prevOpenProgress = openProgress;
        prevClutchProgress = clutchProgress;
        prevBiteProgress = biteProgress;
        prevCosmawPitch = this.getCosmawPitch();
        if (!this.level().isClientSide) {
            final float f2 = (float) -((float) this.getDeltaMovement().y * Mth.RAD_TO_DEG);
            this.setCosmawPitch(this.getCosmawPitch() + 0.6F * (this.getCosmawPitch() + f2) - this.getCosmawPitch());
        }

        if (isMouthOpen()) {
            if (openProgress < 5F)
                openProgress++;
        } else {
            if (openProgress > 0F)
                openProgress--;
        }

        if (isVehicle()) {
            if (clutchProgress < 5F)
                clutchProgress++;
        } else {
            if (clutchProgress > 0F)
                clutchProgress--;
        }

        if (this.entityData.get(ATTACK_TICK) > 0) {
            if (biteProgress < 5F) {
                biteProgress = Math.min(5F, biteProgress + 2F);
            } else {
                if (this.getTarget() != null && this.distanceTo(this.getTarget()) < 3.3D) {
                    if (this.getTarget() instanceof EntityCosmicCod && !this.isTame()) {
                        EntityCosmicCod fish = (EntityCosmicCod) this.getTarget();
                        CompoundTag fishNbt = new CompoundTag();
                        fish.addAdditionalSaveData(fishNbt);
                        fishNbt.putString("DeathLootTable", BuiltInLootTables.EMPTY.toString());
                        fish.readAdditionalSaveData(fishNbt);
                    }
                    this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                }
                this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
            }
        } else {
            if (biteProgress > 0F) {
                biteProgress -= 1F;
            }
        }
        if (!this.getMainHandItem().isEmpty()) {
            heldItemTime++;
            if (heldItemTime > 30 && canTargetItem(this.getMainHandItem())) {
                heldItemTime = 0;
                this.heal(4);
                this.gameEvent(GameEvent.EAT);
                this.playSound(SoundEvents.DOLPHIN_EAT, this.getSoundVolume(), this.getVoicePitch());
                if (this.getMainHandItem().is(AMTagRegistry.COSMAW_TAMEABLES) && fishThrowerID != null && !this.isTame()) {
                    if (getRandom().nextFloat() < 0.3F) {
                        this.setTame(true);
                        this.setCommand(1);
                        this.setOwnerUUID(this.fishThrowerID);
                        Player player = level().getPlayerByUUID(fishThrowerID);
                        if (player instanceof ServerPlayer) {
                            CriteriaTriggers.TAME_ANIMAL.trigger((ServerPlayer) player, this);
                        }
                        this.level().broadcastEntityEvent(this, (byte) 7);
                    } else {
                        this.level().broadcastEntityEvent(this, (byte) 6);
                    }
                }
                if (this.getMainHandItem().hasCraftingRemainingItem()) {
                    this.spawnAtLocation(this.getMainHandItem().getCraftingRemainingItem());
                }
                this.getMainHandItem().shrink(1);
            }
        } else {
            heldItemTime = 0;
        }
        if (!this.level().isClientSide) {
            if (tickCount % 100 == 0 || lastSafeTpPosition == null) {
                BlockPos pos = getCosmawGround(this.blockPosition());
                if (pos.getY() > 1) {
                    lastSafeTpPosition = pos;
                }
            }

            if (this.isVehicle()) {
                if (lastSafeTpPosition != null) {
                    final double dist = this.distanceToSqr(Vec3.atCenterOf(lastSafeTpPosition));
                    float speed = 0.8F;
                    if(this.getY() < -40){
                        speed = 3F;
                    }
                    if (verticalCollision && dist > 14) {
                        this.setYRot(this.stuckRot);
                        if (random.nextInt(50) == 0) {
                            this.stuckRot = Mth.wrapDegrees(this.stuckRot + 90);

                        }
                        final float angle = (Maths.STARTING_ANGLE * stuckRot);
                        final double extraX = -2 * Mth.sin(Mth.PI + angle);
                        final double extraZ = -2 * Mth.cos(angle);
                        this.getMoveControl().setWantedPosition(this.getX() + extraX, this.getY() + 2, this.getZ() + extraZ, speed);
                    } else if (lastSafeTpPosition.getY() > this.getY() + 2.3F) {
                        this.getMoveControl().setWantedPosition(this.getX(), this.getY() + 2, this.getZ(), speed);
                    } else {
                        this.getMoveControl().setWantedPosition(lastSafeTpPosition.getX(), lastSafeTpPosition.getY() + 2, lastSafeTpPosition.getZ(), speed);
                    }
                    if (dist < 7 && getCosmawGround(this.blockPosition()).getY() > 1) {
                        this.ejectPassengers();
                    }
                } else {
                    if (this.getY() < 0F) {
                        this.getDeltaMovement().add(0, 0.75F, 0);
                    } else if (this.getY() < 80F) {
                        this.getDeltaMovement().add(0, 0.1F, 0);
                    }
                }

            }
        }

    }

public boolean doHurtTarget(Entity entityIn) {
        if (this.entityData.get(ATTACK_TICK) == 0 && this.biteProgress == 0) {
            this.entityData.set(ATTACK_TICK, 5);
        }
        return true;
    }

@Override
    public void onGetItem(ItemEntity e) {
        ItemStack duplicate = e.getItem().copy();
        duplicate.setCount(1);
        if (!this.getItemInHand(InteractionHand.MAIN_HAND).isEmpty() && !this.level().isClientSide) {
            this.spawnAtLocation(this.getItemInHand(InteractionHand.MAIN_HAND), 0.0F);
        }
        this.setItemInHand(InteractionHand.MAIN_HAND, duplicate);
        Entity itemThrower = e.getOwner();
        if (e.getItem().is(AMTagRegistry.COSMAW_TAMEABLES) && !this.isTame() && itemThrower != null) {
            fishThrowerID = itemThrower.getUUID();
        } else {
            fishThrowerID = null;
        }
    }

